struct AppState { var count = 0 }
var state = AppState()
state.count += 1
print(state.count)

enum Action { case add }
var count = 0          // state
func send(_ a: Action) { count += 1 }
send(.add)             // view -> action
print(count)           // state -> view

enum Action { case add, reset }
func reduce(_ s: Int, _ a: Action) -> Int {
    a == .add ? s + 1 : 0
}
print(reduce(4, .add))

